ST.xhtml:p:
rTrigCheck(CLK := g_bHGTECHPipeDiameterCheck);

IF rTrigCheck.Q THEN
  g_bHGTECHPipeDiameterCheck:=FALSE;
  g_bHGTECHPipeDiameterCheckDone:=FALSE;
  nHGTECHCheckState:=5;
  Ton1(IN :=FALSE);
END_IF;

CASE nHGTECHCheckState OF
  0:
    nHGTECHCheckState:=0;
  5:(*延时*)
    Ton1(IN :=TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nDelay1)));
    IF Ton1.Q THEN
      Ton1(IN :=FALSE);
      nHGTECHCheckState:=10;
    END_IF;
  10:(*获取当前模拟量*)
    nHGTECHGetValue:=g_niHGTECHPipeDiameterValue;(*检测完成的模拟量*)
    nHGTECHCheckState:=15;
  15:(*对比数据，给出结果*)
    IF nPipeNum=0 THEN
      IF nHGTECHGetValue >= nHGTECHPipeMin1 AND nHGTECHGetValue <= nHGTECHPipeMax1 THEN
        g_bHGTECHPipeDiameterCheckDone:=TRUE;
      ELSE 
       g_bHGTECHPipeDiameterErrorWarn:=TRUE;
       g_bDefineOutputEnableOutOFF16:=TRUE;
      END_IF;
    ELSIF nPipeNum=1 THEN
      IF nHGTECHGetValue >= nHGTECHPipeMin2 AND nHGTECHGetValue <= nHGTECHPipeMax2 THEN
        g_bHGTECHPipeDiameterCheckDone:=TRUE;
      ELSE 
       g_bHGTECHPipeDiameterErrorWarn:=TRUE;
       g_bDefineOutputEnableOutOFF16:=TRUE;
      END_IF;
    ELSIF nPipeNum=2 THEN
      IF nHGTECHGetValue >= nHGTECHPipeMin3 AND nHGTECHGetValue <= nHGTECHPipeMax3 THEN
        g_bHGTECHPipeDiameterCheckDone:=TRUE;
      ELSE 
       g_bHGTECHPipeDiameterErrorWarn:=TRUE;
       g_bDefineOutputEnableOutOFF16:=TRUE;
      END_IF;
    ELSIF nPipeNum=3 THEN
      IF nHGTECHGetValue >= nHGTECHPipeMin4 AND nHGTECHGetValue <= nHGTECHPipeMax4 THEN
        g_bHGTECHPipeDiameterCheckDone:=TRUE;
      ELSE 
       g_bHGTECHPipeDiameterErrorWarn:=TRUE;
       g_bDefineOutputEnableOutOFF16:=TRUE;
      END_IF;
    ELSIF nPipeNum=4 THEN
      IF nHGTECHGetValue >= nHGTECHPipeMin5 AND nHGTECHGetValue <= nHGTECHPipeMax5 THEN
        g_bHGTECHPipeDiameterCheckDone:=TRUE;
      ELSE 
       g_bHGTECHPipeDiameterErrorWarn:=TRUE;
       g_bDefineOutputEnableOutOFF16:=TRUE;
      END_IF;
    END_IF;
    nHGTECHCheckState:=20;
  20:
    nHGTECHCheckState:=20;

END_CASE;

nHGTECHGetValueFB := g_niHGTECHPipeDiameterValue;
IF nPipeNum=0 THEN
  g_dHGTECHChuckMoveToPos:=dChuckMoveToCutting1;
ELSIF nPipeNum=1 THEN
  g_dHGTECHChuckMoveToPos:=dChuckMoveToCutting2;
ELSIF nPipeNum=2 THEN
  g_dHGTECHChuckMoveToPos:=dChuckMoveToCutting3;
ELSIF nPipeNum=3 THEN
  g_dHGTECHChuckMoveToPos:=dChuckMoveToCutting4;
ELSIF nPipeNum=4 THEN 
  g_dHGTECHChuckMoveToPos:=dChuckMoveToCutting5;
END_IF;

IF g_bPlcResetBuffer THEN
  nHGTECHCheckState:=0;
  g_bHGTECHPipeDiameterCheckDone:=FALSE;
  g_bHGTECHPipeDiameterErrorWarn:=FALSE;
  Ton1(IN :=FALSE);
END_IF;
